import{_ as o,H as a,c as s,b as c,a0 as e,K as i}from"./chunks/framework.DZ_FiXNr.js";const r="/images/connections_add.webp",_=JSON.parse('{"title":"Connections","description":"Manage connected podcast accounts and the AI assistants that can read your PodSEO data from Settings → Connections. Use this page when you need to check access, reconnect an account, or disconnect the right service for the right show.","frontmatter":{},"headers":[],"relativePath":"features/connections.md","filePath":"features/connections.md"}'),d={name:"features/connections.md"};function h(l,n,p,u,g,m){const t=a("HelpWalkthrough");return c(),s("div",null,[n[0]||(n[0]=e('<h1 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h1><p>Manage connected podcast accounts and the AI assistants that can read your PodSEO data from <strong>Settings → Connections</strong>. Use this page when you need to check access, reconnect an account, or disconnect the right service for the right show.</p><h2 id="find-the-account-that-needs-attention" tabindex="-1">Find the account that needs attention <a class="header-anchor" href="#find-the-account-that-needs-attention" aria-label="Permalink to &quot;Find the account that needs attention&quot;">​</a></h2><ol><li>Choose the podcast in the filter, then select <strong>Needs attention</strong>.</li><li>Expand the provider&#39;s <strong>Details</strong> to check its identity, status, and next action. For social providers, open <strong>Accounts &amp; actions</strong> first.</li><li>Before removing access, read <strong>Disconnect…</strong> or <strong>Cancel request…</strong>. Choose <strong>Keep connection</strong> or <strong>Keep request</strong> to leave it unchanged.</li></ol>',4)),i(t,{src:"/walkthroughs/connections-detail.webp",poster:"/images/connections.webp",alt:"Filter a podcast's connections, inspect an account that needs attention, and review cancel and disconnect confirmations without removing access",duration:46100,autoplay:"",loop:"",sample:""}),n[1]||(n[1]=e('<p>Check both the podcast and connected identity before changing access. A social platform can have several connected accounts. The walkthrough leaves its example connections in place.</p><h2 id="add-a-connection" tabindex="-1">Add a connection <a class="header-anchor" href="#add-a-connection" aria-label="Permalink to &quot;Add a connection&quot;">​</a></h2><ol><li>Click <strong>Add connection</strong>.</li><li>Choose <strong>AI assistant</strong>, or find your podcast under <strong>Podcast account</strong>.</li><li>For that podcast, choose <strong>Social accounts</strong> to connect a publishing destination, or <strong>Analytics</strong> for the source&#39;s setup guide.</li><li>Complete the provider&#39;s sign-in or invitation steps, then check the status back in PodSEO.</li></ol><p><a href="/images/connections_add.webp" title="Open screenshot at full size"><img src="'+r+'" alt="Add a connection: choose a podcast&#39;s social accounts or analytics"></a></p><p>Analytics setup stays in <a href="/features/analytics-connections.html">Analytics</a>, where you also read its reports. Social destinations are used by <a href="/features/social-publishing.html">Social Publishing</a>. Google sign-in for your PodSEO login is separate and stays in <strong>Settings → Account</strong>.</p><h2 id="reconnect-or-disconnect" tabindex="-1">Reconnect or disconnect <a class="header-anchor" href="#reconnect-or-disconnect" aria-label="Permalink to &quot;Reconnect or disconnect&quot;">​</a></h2><p>A connection that needs attention offers the relevant next step. Open it, follow the instructions, and verify the correct account is connected before relying on future updates or scheduled posts.</p><p>To disconnect, expand the account and choose <strong>Disconnect…</strong>. For an unfinished request, the action can be <strong>Cancel request…</strong>. Read the confirmation: it explains what will stop working and whether you must also remove access on the provider&#39;s website.</p><p>Disconnecting an analytics source stops new imports; disconnecting a social destination can prevent scheduled posts from publishing there. Removing a connection does not cancel your PodSEO subscription. The confirmation and <a href="/features/analytics-connections.html">source guide</a> explain whether saved numbers are retained or deleted.</p><h2 id="ai-assistants-are-personal" tabindex="-1">AI assistants are personal <a class="header-anchor" href="#ai-assistants-are-personal" aria-label="Permalink to &quot;AI assistants are personal&quot;">​</a></h2><p>The <strong>AI assistants</strong> section lists the assistants you connected and the account each can read. Those authorizations belong to your login, while social and analytics accounts belong to the podcast workspace. Use <strong>Connect an AI assistant</strong> for the server URL and setup steps; see <a href="/features/ai-connections.html">AI Connections</a>.</p><h2 id="who-can-manage-connections" tabindex="-1">Who can manage connections? <a class="header-anchor" href="#who-can-manage-connections" aria-label="Permalink to &quot;Who can manage connections?&quot;">​</a></h2><p>In a personal account, you manage your own podcast connections. In an organization, only <strong>Owners</strong> and <strong>Admins</strong> manage podcast connections. Other members can still manage their own AI assistant authorizations when the approved account&#39;s plan supports them.</p>',13))])}const b=o(d,[["render",h]]);export{_ as __pageData,b as default};
